import { decodeTournament, encodeTournament } from './format.ts';
import type { Tournament } from './rules.ts';
const KEY = 'neon-pairs.tournaments.v1';
export function readHistory(): { items: Tournament[]; blocked: boolean } {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return { items: [], blocked: false };
    const value: unknown = JSON.parse(raw);
    if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).sort().join(',') !== 'items,v' || !('v' in value) || value.v !== 3 || !('items' in value) || !Array.isArray(value.items)) return { items: [], blocked: false };
    const items = value.items.map((item: unknown) => decodeTournament(JSON.stringify(item)).tournament);
    return { items: items.every((t: Tournament | null) => t?.phase === 'complete') ? items as Tournament[] : [], blocked: false };
  } catch { return { items: [], blocked: true }; }
}
export function saveHistory(items: Tournament[]): boolean {
  try { localStorage.setItem(KEY, JSON.stringify({ v: 3, items: items.map((item) => JSON.parse(encodeTournament(item))) })); return true; }
  catch { return false; }
}
