    const finished = recordResult(event, { moves: game.session.game.moves, elapsedMs: game.session.game.elapsedMs });
    setEvent(finished);
    if (finished.phase === 'complete') {
      setHistory((old) => { const items = [finished, ...old.items].slice(0, 10); return { items, blocked: !saveHistory(items) }; });
      announce(`Champion: ${finished.names[currentMatch(finished).winner!]}`);
    } else announce(finished.phase === 'turn' ? `Now playing: ${finished.names[currentPlayer(finished)]}` : `Winner: ${finished.names[currentMatch(finished).winner!]}`);
  }, [event, game.session.game]);
  function confirm(action: () => void) {
    if (!event || event.phase === 'complete') { action(); return; }
    pending.current = action; dialog.current?.showModal(); keep.current?.focus();
  }
  function start() {
    const result = normalizeNames(names.slice(0, count));
    if (result.error) { announce(result.error); return; }
    setEvent(createTournament(result.names, deals(roundSize(count / 2), count / 2, [])));
    announce(`Now playing: ${result.names[0]}`);
  }
  function startTurn() {
    if (!event) return;
    game.startDeal(currentMatch(event).code);
    setEvent({ ...event, phase: 'playing' });
  }
  function advance() {
    if (!event) return;
    if (event.phase === 'turn') { const next = { ...event, phase: 'ready' as const }; setEvent(next); announce(`Now playing: ${next.names[currentPlayer(next)]}`); return; }
    const last = event.rounds.at(-1)!;
    const used = event.rounds.flatMap((r) => r.map((m) => m.code));
    const next = nextMatch(event, last.every((m) => m.winner !== null) ? deals(roundSize(last.length / 2), last.length / 2, used) : []);
    setEvent(next); announce(`Now playing: ${next.names[currentPlayer(next)]}`);
  }
  function exportEvent() {
