    <h2 ref={heading} tabIndex={-1}>Tournament</h2>
    {!event && <><div className="tournament-form"><label htmlFor="players">Players</label><select id="players" className="control" value={count} onChange={(e) => setCount(Number(e.target.value))}><option value={4}>4</option><option value={8}>8</option></select>
      {names.slice(0, count).map((name, i) => <label key={i}>Player {i + 1}<input className="control" value={name} onChange={(e) => setNames((old) => old.map ( (n, j) => i === j ? e.target.value : n))} /></label>)}
      <button className="control" onClick={start}>Start tournament</button></div>
      <h3>Past tournaments</h3>{history.blocked && <p>Progress won't be saved on this device.</p>}
      {history.items.length === 0 ? <p>No past tournaments.</p> : <ul>{history.items.map((past, i) => <li key={i}><button className="control" onClick={() => { setEvent(past); announce('Tournament loaded.'); }}>Champion: {past.names[currentMatch(past).winner!]}</button></li>)}</ul>}
      <button className="control" onClick={back}>Back to game</button></>}
    {event && match && <><p>Round: {roundName(event.rounds.at(-1)!.length)}</p>
      {event.phase === 'complete' ? <><p>Champion: {event.names[match.winner!]}</p><button className="control" onClick={back}>Back to game</button></> : <><p>Now playing: {event.names[currentPlayer(event)]}</p>
      {event.phase === 'ready' && <button className="control" onClick={startTurn}>Start turn</button>}
      {event.phase === 'playing' && game.session.paused && <button className="control" onClick={game.resume}>Resume</button>}
      {event.phase === 'turn' && <button className="control" onClick={advance}>Next turn</button>}
      {event.phase === 'match' && <button className="control" onClick={advance}>Next match</button>}
      <button className="control" onClick={() => confirm(back)}>Leave tournament</button></>}
      {event.phase === 'playing' && <><GameStatus game={game.session.game} best={undefined} celebration={game.session.celebration} /><p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p><Board key={game.session.generation} game={game.session.game} activate={game.activate} ref={board} /></>}
      <Bracket tournament={event} /></>}
    <div className="game-result"><p role="status" aria-live="polite" aria-atomic="true"><span key={`${announcement}-${game.session.announcement}`}>{notice || game.session.feedback}</span></p></div>
    <div className="tournament-exchange"><label htmlFor="tournament-json">Tournament JSON</label><textarea id="tournament-json" className="control" value={draft} onChange={(e) => setDraft(e.target.value)} /><div><button className="control" onClick={exportEvent}>Export tournament</button><button className="control" onClick={load}>Load tournament</button></div></div>
    <dialog ref={dialog} onCancel={() => { pending.current = null; }}><p>Leave this unfinished tournament?</p><button ref={keep} className="control" onClick={() => { pending.current = null; dialog.current?.close(); }}>Keep playing</button><button className="control" onClick={() => { dialog.current?.close(); pending.current?.(); pending.current = null; }}>Leave</button></dialog>
  </section>;
}
